from pathlib import Path
p=Path('src/components/accounting.tsx');s=p.read_text(encoding='utf-8');s=s.replace('warehouseId?:string;documents?', 'warehouseId?:string;employeeEmail?:string;documents?');s=s.replace('useState<{id:string;name:string;city:string}[]>','useState<{id:string;name:string;city:string;staff?:string[];staffNames?:Record<string,string>}[]>')
s=s.replace(' function newEntry(', " const warehouseStaff=warehouses.find(w=>w.id===warehouseId)\n const employees=(warehouseStaff?.staff||[]).map(email=>({email,name:warehouseStaff?.staffNames?.[email]||email}))\n function newEntry(")
old='<Input id="entry-person" required={draft.kind===\'work\'||draft.kind===\'invoice\'} value={draft.person} onChange={e=>setDraft({...draft,person:e.target.value})}/>'
new='''{draft.kind==='work'?<><Select value={draft.employeeEmail||employees.find(employee=>employee.name===draft.person)?.email||''} onValueChange={email=>{const employee=employees.find(item=>item.email===email);if(employee)setDraft({...draft,person:employee.name,employeeEmail:email})}}><SelectTrigger id="entry-person" className="w-full" aria-label="Сотрудник"><SelectValue placeholder="Выберите сотрудника"/></SelectTrigger><SelectContent>{employees.map(employee=><SelectItem key={employee.email} value={employee.email}>{employee.name}</SelectItem>)}{!employees.length&&<SelectItem value="empty" disabled>Нет добавленных сотрудников</SelectItem>}</SelectContent></Select>{!employees.length&&<p className="text-sm text-muted-foreground">Добавьте сотрудников в разделе «Склады».</p>}</>:<Input id="entry-person" required={draft.kind==='invoice'} value={draft.person} onChange={e=>setDraft({...draft,person:e.target.value})}/>}'''
assert old in s;s=s.replace(old,new)
s=s.replace("if(!draft.date){", "if(draft.kind==='work'&&!employees.some(employee=>employee.email===draft.employeeEmail||employee.name===draft.person)){toast.error('Выберите сотрудника склада');return;}if(!draft.date){")
p.write_text(s,encoding='utf-8')
